allow:
Bash(sudo sed -i '/# SmartSpecWeb APIs \(services, tenants, etc.\) - route to Node.js/,/^    }/{
  /^    }$/a    # Admin tenants API - route to Node.js    location /api/admin/tenants {        proxy_pass http://localhost:3000;        proxy_http_version 1.1;        proxy_set_header Host $host;        proxy_set_header X-Real-IP $remote_addr;        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;        proxy_set_header X-Forwarded-Proto $scheme;        proxy_connect_timeout 60s;        proxy_send_timeout 60s;        proxy_read_timeout 60s;        client_max_body_size 10M;    }
}' /etc/nginx/sites-enabled/smartspec)

Bash(DATABASE_URL="postgresql://smartspec:smartspec_dev@localhost:5432/smartspec" npx tsx -e "
import postgres from ''postgres'';
const sql = postgres\(process.env.DATABASE_URL!\);
async function main\(\) {
  await sql.unsafe\(""ALTER TYPE entity_type ADD VALUE IF NOT EXISTS ''rule''""\);
  console.log\(''Done: added rule to entity_type enum''\);
  await sql.end\(\);
}
main\(\).catch\(e => { console.error\(e.message\); process.exit\(1\); }\);
")
